function humanDay(raw) {
  if (raw === undefined || raw === null) return '';
  var s = String(raw);
  if (s === '') return '';
  var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  var at = m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : new Date(s);
  if (isNaN(at.getTime())) return '';
  return at.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
}
if (Inputs.standing === undefined) return;
const LABELS = {"moderator":"Moderator","member":"Member"};
const standing = Inputs.standing === null ? '' : String(Inputs.standing);
// ⚠️ An unknown standing falls back to the stored word rather than to
// an empty line: a row that says `trustee` is legible, and a row that
// says nothing at all is the bug that hides the new standing nobody
// added a label for.
const label = LABELS[standing] || standing;
// The column is a full ISO timestamp; the day is what a person wants —
// and D25: this was the one site rendering it as `2026-08-29`.
const day = humanDay(Inputs.joinedAt);
Outputs.description = day.length > 0 ? label + ' · since ' + day : label;
